package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Tag;
import org.jsoup.parser.TagType;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FormElement_formData_TriageGen0Test {

    private FormElement formElement;

    @Before
    public void setUp() {
        Tag tag = new Tag(TagType.INPUT, "input", Attributes.empty(), null);
        Element inputElement = new Element(TagType.INPUT, "input", Attributes.empty(), "<input>", null);
        formElement = new FormElement(tag, "http://example.com/", Attributes.empty());
        formElement.addElement(inputElement);
    }

    @Test
    public void testFormData_NoElements() {
        FormElement form = new FormElement(new Tag(TagType.FORM, "form", Attributes.empty(), null), "http://example.com/", Attributes.empty());
        List<Connection.KeyVal> data = form.formData();
        assertEquals(0, data.size());
    }

    @Test
    public void testFormData_NoNameAttribute() {
        Element inputElement = new Element(TagType.INPUT, "input", Attributes.empty(), "<input>", null);
        formElement.addElement(inputElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(0, data.size());
    }

    @Test
    public void testFormData_TextInput() {
        Element inputElement = new Element(TagType.INPUT, "input", Attributes.of("name", "text", "value", "hello"), "<input>", null);
        formElement.addElement(inputElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(1, data.size());
        assertEquals("text", data.get(0).getKey());
        assertEquals("hello", data.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxChecked() {
        Element checkboxElement = new Element(TagType.INPUT, "input", Attributes.of("name", "checkbox", "type", "checkbox", "checked", "checked"), "<input>", null);
        formElement.addElement(checkboxElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(1, data.size());
        assertEquals("checkbox", data.get(0).getKey());
        assertEquals("", data.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        Element checkboxElement = new Element(TagType.INPUT, "input", Attributes.of("name", "checkbox", "type", "checkbox"), "<input>", null);
        formElement.addElement(checkboxElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(0, data.size());
    }

    @Test
    public void testFormData_RadioChecked() {
        Element radioElement = new Element(TagType.INPUT, "input", Attributes.of("name", "radio", "type", "radio", "checked", "checked"), "<input>", null);
        formElement.addElement(radioElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(1, data.size());
        assertEquals("radio", data.get(0).getKey());
        assertEquals("", data.get(0).getValue());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        Element radioElement = new Element(TagType.INPUT, "input", Attributes.of("name", "radio", "type", "radio"), "<input>", null);
        formElement.addElement(radioElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(0, data.size());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        Element selectElement = new Element(TagType.SELECT, "select", Attributes.of("name", "dropdown"), "<select><option selected value='1'>One</option></select>", null);
        formElement.addElement(selectElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(1, data.size());
        assertEquals("dropdown", data.get(0).getKey());
        assertEquals("1", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithoutSelectedOption() {
        Element selectElement = new Element(TagType.SELECT, "select", Attributes.of("name", "dropdown"), "<select><option value='1'>One</option></select>", null);
        formElement.addElement(selectElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(1, data.size());
        assertEquals("dropdown", data.get(0).getKey());
        assertEquals("1", data.get(0).getValue());
    }

    @Test
    public void testFormData_MultipleSelectOptions() {
        Element selectElement = new Element(TagType.SELECT, "select", Attributes.of("name", "dropdown"), "<select><option selected value='1'>One</option><option selected value='2'>Two</option></select>", null);
        formElement.addElement(selectElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(2, data.size());
        assertEquals("dropdown", data.get(0).getKey());
        assertEquals("1", data.get(0).getValue());
        assertEquals("dropdown", data.get(1).getKey());
        assertEquals("2", data.get(1).getValue());
    }

    @Test
    public void testFormData_MixedElements() {
        Element inputElement = new Element(TagType.INPUT, "input", Attributes.of("name", "text", "value", "hello"), "<input>", null);
        Element checkboxElement = new Element(TagType.INPUT, "input", Attributes.of("name", "checkbox", "type", "checkbox", "checked", "checked"), "<input>", null);
        Element selectElement = new Element(TagType.SELECT, "select", Attributes.of("name", "dropdown"), "<select><option selected value='1'>One</option></select>", null);
        formElement.addElement(inputElement);
        formElement.addElement(checkboxElement);
        formElement.addElement(selectElement);
        List<Connection.KeyVal> data = formElement.formData();
        assertEquals(3, data.size());
        assertEquals("text", data.get(0).getKey());
        assertEquals("hello", data.get(0).getValue());
        assertEquals("checkbox", data.get(1).getKey());
        assertEquals("", data.get(1).getValue());
        assertEquals("dropdown", data.get(2).getKey());
        assertEquals("1", data.get(2).getValue());
    }
}
